function diagram(boxes,arrows,w,h,label){
 const bx=boxes.map(([x,y,bw,bh,t])=>`<rect x="${x}" y="${y}" width="${bw}" height="${bh}" rx="9"/><text x="${x+bw/2}" y="${y+bh/2+5}" text-anchor="middle">${esc(t)}</text>`).join('');
 const lines=arrows.map(([x1,y1,x2,y2])=>`<path d="M${x1},${y1} L${x2},${y2}" marker-end="url(#${label})"/>`).join('');
 return `<svg role="img" aria-label="${esc(label)}" viewBox="0 0 ${w} ${h}"><defs><marker id="${label}" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto"><path d="M0,0 L0,6 L9,3 z" class="arrow"/></marker></defs>${lines}${bx}</svg>`;
}
